ions:[TextButton(onPressed:()=>Navigator.pop(dialog),child:const Text('Cancel')),FilledButton(onPressed:saving||photo.isEmpty?null:()async{update(()=>saving=true);try{await api.request('/issues',method:'POST',body:{'title':title.text,'description':description.text,'category':category,'location':{'entrance':area.isEmpty?entrance:0,'floor':area.isEmpty?floor:0,'area':area},'photo':photo});if(dialog.mounted)Navigator.pop(dialog);await refresh();}catch(e){if(c.mounted)update(()=>message=e.toString().replaceFirst('Exception: ',''));}finally{if(c.mounted)update(()=>saving=false);}},child:Text(saving?'Sending…':'Submit issue'))])));
